begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
create function pg_temp.denied(sql text) returns void language plpgsql as $$ begin begin execute sql; exception when others then return; end; raise exception 'expected denied'; end; $$;
insert into auth.users(id,email) values ('00000080-0000-4000-8000-000000000001','cancel-admin@example.invalid'),('00000080-0000-4000-8000-000000000002','cancel-owner@example.invalid');
insert into public.profiles(id,name,role) values ('00000080-0000-4000-8000-000000000001','Cancel Admin','ADMIN'),('00000080-0000-4000-8000-000000000002','Cancel Owner','USER');
insert into public.admin_accounts(profile_id,duty) values ('00000080-0000-4000-8000-000000000001','정산');
insert into public.reservations(id,code,customer_id,plan,patient_name,patient_birth,patient_gender,patient_phone,guardian_name,guardian_phone,relation,treatment,purpose,use_date,arrive_time,reserve_time,duration,duration_minutes,depart_address,hospital_address)
values ('00000080-0000-4000-8000-000000000003','TEST-CANCEL-80','00000080-0000-4000-8000-000000000002','basic','Test','1960-01-01','female','01000000000','Test','01000000000','self','Test','Test','2099-01-01','09:00','09:00','2시간',120,'Test','Test');
insert into public.payments(id,reservation_id,type,status,order_id,gross_amount,payout_amount) values ('00000080-0000-4000-8000-000000000004','00000080-0000-4000-8000-000000000003','BASE','FAILED','TEST-CANCEL-PAY',1000,1000);
insert into public.payment_incidents(id,payment_id,kind,severity) values ('00000080-0000-4000-8000-000000000005','00000080-0000-4000-8000-000000000004','CANCEL_FAILED','CRITICAL');
select set_config('request.jwt.claims','{"sub":"00000080-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select pg_temp.denied($q$select public.admin_claim_incident_cancel('00000080-0000-4000-8000-000000000005','test recovery')$q$);
reset role;
select set_config('request.jwt.claims','{"sub":"00000080-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
update public.admin_accounts set duty='계정' where profile_id='00000080-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.denied($q$select public.admin_claim_incident_cancel('00000080-0000-4000-8000-000000000005','test recovery')$q$);
reset role;
update public.admin_accounts set duty='정산' where profile_id='00000080-0000-4000-8000-000000000001';
update public.payments set status='PAID' where id='00000080-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.denied($q$select public.admin_claim_incident_cancel('00000080-0000-4000-8000-000000000005','test recovery')$q$);
reset role;
update public.payments set status='FAILED' where id='00000080-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.assert((public.admin_claim_incident_cancel('00000080-0000-4000-8000-000000000005','test recovery')->>'amount')::integer=1000,'claim amount');
select pg_temp.denied($q$select public.admin_claim_incident_cancel('00000080-0000-4000-8000-000000000005','test recovery')$q$);
select pg_temp.denied($q$select public.record_incident_cancel('00000080-0000-4000-8000-000000000004',true,'test-tid')$q$);
reset role;
select public.record_incident_cancel('00000080-0000-4000-8000-000000000004',false,'test-tid');
select pg_temp.assert(status='UNKNOWN','unknown protected') from public.payment_incident_cancellations;
select public.record_incident_cancel('00000080-0000-4000-8000-000000000004',true,'test-tid');
select pg_temp.assert(status='CANCELLED','cancelled persisted') from public.payments where id='00000080-0000-4000-8000-000000000004';
select pg_temp.assert(exists(select 1 from public.access_logs where action='INCIDENT_CANCEL_COMPLETED' and actor_id='00000080-0000-4000-8000-000000000001'),'audit actor persisted');
-- 사고 보유기간이 결제 원장보다 짧아도 재취소 방지 기록은 결제와 함께 유지한다.
delete from public.payment_incidents where id='00000080-0000-4000-8000-000000000005';
select pg_temp.assert(exists(select 1 from public.payment_incident_cancellations where payment_id='00000080-0000-4000-8000-000000000004' and incident_id is null),'claim survives incident deletion');
rollback;
